-c "import hashlib, json, os, pathlib, re, select, shutil, signal, subprocess, sys, tempfile, time, uuid

class DLCError(Exception):
    pass

def parse_entries(keys_text, sources_text):
    keys, sources = {}, {}
    for raw in keys_text.replace(chr(10), ';').replace(chr(13), ';').split(';'):
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), ''.join(value.split()).upper()
        if not sep or not re.fullmatch('[a-z][a-z0-9_-]{0,47}', alias):
            raise DLCError('Invalid DLC key entry; use NAME=KEY separated by semicolons.')
        if alias in keys:
            raise DLCError('Duplicate DLC key name: ' + alias)
        if not re.fullmatch('[A-Z0-9-]{10,80}', value):
            raise DLCError('Invalid product key format for ' + alias)
        keys[alias] = value
    for raw in sources_text.splitlines():
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), value.strip()
        if not sep or alias not in keys or not value:
            raise DLCError('Every source needs NAME=SOURCE and a matching DLC key name.')
        if alias in sources:
            raise DLCError('Duplicate DLC source name: ' + alias)
        if any(ord(c) < 32 for c in value):
            raise DLCError('Invalid control character in source for ' + alias)
        sources[alias] = value
    return keys, sources

def fingerprint(keys, sources):
    data = json.dumps([keys, sources], sort_keys=True).encode()
    return hashlib.sha256(data).hexdigest()

def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1048576), b''):
            h.update(chunk)
    return h.hexdigest()

def payloads(profile):
    result = {}
    for path in (profile / 'pdlc').glob('*.dlc'):
        if path.is_symlink() or not path.is_file() or path.stat().st_size < 64:
            continue
        with path.open('rb') as stream:
            if b'<dlcstub' in stream.read(4096).lower():
                continue
        result[path.name] = {'sha256': digest(path), 'mtime': path.stat().st_mtime_ns}
    return result

def payload_stats(profile):
    return {p.name: (p.stat().st_size, p.stat().st_mtime_ns) for p in (profile / 'pdlc').glob('*.dlc') if p.is_file() and not p.is_symlink()}

def already_installed(record, prefix_id, current):
    files = record.get('files', {})
    return record.get('prefix') == prefix_id and bool(files) and all(
        name in current and current[name]['sha256'] == checksum for name, checksum in files.items())

def image_setup(image, destination):
    tool = shutil.which('7z') or shutil.which('7zz')
    if not tool:
        raise DLCError('IMG sources need 7z; install p7zip-full in the instance container.')
    listing = subprocess.run([tool, 'l', '-slt', '-ba', str(image)], capture_output=True, text=True, timeout=120)
    if listing.returncode:
        raise DLCError('The DLC image could not be read by 7z.')
    total, files = 0, []
    for block in listing.stdout.split(chr(10) + chr(10)):
        fields = dict(line.split(' = ', 1) for line in block.splitlines() if ' = ' in line)
        if 'Path' not in fields:
            continue
        name = fields['Path'].replace(chr(92), '/')
        relative = pathlib.PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts or ':' in name:
            raise DLCError('The DLC image contains an invalid path.')
        if any(('Link' in key or 'Reparse' in key) and value.strip() for key, value in fields.items() if key != 'Links'):
            raise DLCError('Links inside DLC images are not supported.')
        total += int(fields.get('Size', '0'))
        files.append(relative)
    if not files or len(files) > 10000:
        raise DLCError('The DLC image is empty or has too many entries.')
    if shutil.disk_usage(destination).free < total + 536870912:
        raise DLCError('Not enough free space to unpack the DLC image.')
    result = subprocess.run([tool, 'x', '-y', '-o' + str(destination), str(image)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=1800)
    if result.returncode:
        raise DLCError('DLC image extraction failed.')
    for path in destination.rglob('*'):
        if path.is_symlink() or destination.resolve() not in path.resolve().parents:
            raise DLCError('The extracted DLC image contains an invalid link or path.')
    setups = [p for p in destination.rglob('*') if p.is_file() and p.name.lower() == 'setup.exe']
    candidates = setups or [p for p in destination.rglob('*') if p.is_file() and p.suffix.lower() == '.exe' and not p.name.lower().startswith(('unins', 'autorun'))]
    if len(candidates) != 1:
        raise DLCError('The DLC image must contain one unambiguous installer.')
    return candidates[0]

def stop_process(process):
    if process.poll() is not None:
        return
    try:
        os.killpg(process.pid, signal.SIGTERM)
    except ProcessLookupError:
        return
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        process.wait(timeout=5)

def start_display(env):
    process = subprocess.Popen(['Xvfb', '-displayfd', '1', '-screen', '0', '1280x720x24', '-nolisten', 'tcp'], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, start_new_session=True)
    try:
        if not select.select([process.stdout], [], [], 10)[0]:
            raise DLCError('The DLC virtual display did not start.')
        number = process.stdout.readline().decode().strip()
        if not number.isdigit() or process.poll() is not None:
            raise DLCError('The DLC virtual display failed.')
        env['DISPLAY'] = ':' + number
        return process
    except BaseException:
        stop_process(process)
        raise

def success_dialog(proton, env):
    def inspect(command):
        result = subprocess.run([str(proton), 'runinprefix', 'winedbg', '--command', command], env=env, capture_output=True, text=True, timeout=20)
        return result.stdout if result.returncode == 0 else ''
    listing = inspect('info wnd')
    stack, candidates = [], []
    for line in listing.splitlines():
        match = re.fullmatch(r'( *)([0-9a-fA-F]+)\s+(\S+)\s+([0-9a-fA-F]{8})\s+[0-9a-fA-F]+\s+[0-9a-fA-F]+\s+(.*)', line)
        if not match:
            continue
        indent, handle, kind, style, text = match.groups()
        depth, visible = len(indent), bool(int(style, 16) & 0x10000000)
        while stack and stack[-1][0] >= depth:
            stack.pop()
        if kind == 'Static' and visible and text == 'Installation s' and stack:
            parent = stack[-1]
            if parent[2] == '#32770' and parent[3] and parent[4].startswith('Farming Simula'):
                candidates.append((parent[1], handle))
        stack.append((depth, handle, kind, visible, text))
    if len(candidates) != 1:
        return False
    parent, child = candidates[0]
    parent_info = inspect('info * wnd 0x' + parent)
    child_info = inspect('info * wnd 0x' + child)
    return bool(re.search(r\"class='#32770'\", parent_info) and re.search(r\"text='Farming Simulator 25 - [^']+'\", parent_info) and re.search(r\"class='Static'\", child_info) and re.search(r\"text='Installation successful[.]'\", child_info))

def install_one(installer, key, profile, proton, env, timeout):
    before, before_stats = payloads(profile), payload_stats(profile)
    process = subprocess.Popen([str(proton), 'runinprefix', str(installer)], cwd=installer.parent, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    entered, last_confirm, success_confirmed = False, 0, False
    deadline = time.monotonic() + timeout
    print('DLC activation: waiting for the GIANTS product-key dialog.', flush=True)
    try:
        while process.poll() is None:
            if time.monotonic() >= deadline:
                raise DLCError('The DLC installer timed out; no installed marker was written.')
            search = subprocess.run(['xdotool', 'search', '--onlyvisible', '--name', '^FarmingSimulator2025([[:space:]]+v[0-9]+)?$'], env=env, capture_output=True, text=True, timeout=10)
            windows = [line for line in search.stdout.splitlines() if line.isdigit()]
            if windows and not entered:
                window = windows[0]
                print('DLC activation: product-key dialog detected; entering configured key.', flush=True)
                for command in (['windowfocus', '--sync', window], ['key', '--clearmodifiers', 'ctrl+a'], ['type', '--clearmodifiers', '--delay', '40', key.replace('-', '')], ['key', '--clearmodifiers', 'Return']):
                    result = subprocess.run(['xdotool'] + command, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15)
                    if result.returncode:
                        raise DLCError('The DLC product key dialog could not be controlled.')
                entered = True
                print('DLC activation: configured key submitted; waiting for GIANTS installer to finish.', flush=True)
            current = payload_stats(profile)
            changed = any(name not in before_stats or data != before_stats[name] for name, data in current.items())
            if changed and time.monotonic() - last_confirm >= 5:
                confirmation = subprocess.run(['xdotool', 'search', '--onlyvisible', '--name', '^Farming Simulator 25 - .+$'], env=env, capture_output=True, text=True, timeout=10)
                dialogs = [line for line in confirmation.stdout.splitlines() if line.isdigit() and line not in windows]
                if len(dialogs) == 1:
                    if not success_dialog(proton, env):
                        raise DLCError('The GIANTS result dialog did not confirm a successful installation; no installed marker was written.')
                    success_confirmed = True
                    for command in (['windowfocus', '--sync', dialogs[0]], ['key', '--clearmodifiers', 'Return']):
                        result = subprocess.run(['xdotool'] + command, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15)
                        if result.returncode:
                            raise DLCError('The DLC completion dialog could not be controlled.')
                    print('DLC activation: payload detected; GIANTS completion dialog confirmed.', flush=True)
                    last_confirm = time.monotonic()
            time.sleep(2)
        if process.returncode != 0 and not (process.returncode == 1 and success_confirmed):
            raise DLCError('The DLC installer exited with status ' + str(process.returncode) + '; no installed marker was written.')
        after = payloads(profile)
        changed = {name: data['sha256'] for name, data in after.items() if name not in before or data != before[name]}
        if not changed:
            raise DLCError('The installer exited without producing a new or updated non-stub DLC payload.')
        if process.returncode == 1:
            print('DLC activation: GIANTS reported success; natural exit code 1 and changed payload verified.', flush=True)
        return changed
    finally:
        stop_process(process)

def install(base, proton, prefix, timeout, keys, sources):
    work, profile = base / 'work' / 'dlc', base / 'profile'
    if not (base / 'game' / '.amp-install-complete').is_file() or not (base / 'game' / 'dedicatedServer.exe').is_file():
        raise DLCError('Install the complete FS25 base game successfully before installing DLCs.')
    if not (profile / 'AHC_63805.dat').is_file():
        raise DLCError('Activate the FS25 base game successfully before installing DLCs.')
    try:
        pending = json.loads((work / 'pending.json').read_text())
    except (OSError, ValueError):
        raise DLCError('No prepared DLC downloads; stop the instance and run Update first.') from None
    if pending.get('schema') != 1 or pending.get('configuration') != fingerprint(keys, sources):
        raise DLCError('DLC settings changed; stop the instance and run Update before starting.')
    if pending.get('aliases') != sorted(keys) or not pending.get('jobs'):
        raise DLCError('The prepared DLC list is incomplete; run Update again.')
    pfx = prefix / 'pfx'
    if not proton.is_file() or not (pfx / 'system.reg').is_file() or not profile.is_dir():
        raise DLCError('The base game, permanent profile and Proton prefix must be prepared first.')
    documents = (pfx / 'drive_c' / 'users' / 'steamuser' / 'Documents' / 'My Games' / 'FarmingSimulator2025').resolve()
    if documents != profile.resolve():
        raise DLCError('The DLC installer and dedicated server do not share the same game profile.')
    token_file = pfx / '.amp-dlc-prefix-id'
    if not token_file.exists():
        token_file.write_text(str(uuid.uuid4()), encoding='ascii')
    token = token_file.read_text(encoding='ascii').strip()
    records = {}
    state_file = work / 'installed.json'
    try:
        records = json.loads(state_file.read_text()).get('installers', {})
    except (OSError, ValueError):
        pass
    current, queue = payloads(profile), []
    for job in pending['jobs']:
        alias, checksum = job.get('alias'), job.get('sha256', '')
        name = job.get('installer', '')
        if alias not in keys or not re.fullmatch('[a-f0-9]{64}', checksum) or name not in (checksum + '.exe', checksum + '.img'):
            raise DLCError('Invalid pending DLC entry; run Update again.')
        path = work / name
        if not path.is_file() or path.is_symlink() or digest(path) != checksum:
            raise DLCError('DLC installer missing or changed; run Update again.')
        if already_installed(records.get(checksum, {}), token, current):
            print('DLC ' + alias + ': verified installed payload; skipping installer.', flush=True)
        else:
            queue.append((job, path))
    if not queue:
        return
    for tool in ('xdotool', 'Xvfb'):
        if not shutil.which(tool):
            raise DLCError('DLC installation requires ' + tool + ' in the instance runtime.')
    env = dict(os.environ, STEAM_COMPAT_DATA_PATH=str(prefix), STEAM_COMPAT_CLIENT_INSTALL_PATH=str(base / '.steam' / 'steam'), HOME=str(base), WINEDEBUG='-all')
    display = start_display(env)
    try:
        for job, path in queue:
            alias = job['alias']
            print('DLC ' + alias + ': starting the GIANTS installer.', flush=True)
            with tempfile.TemporaryDirectory(prefix='extract-', dir=work) as directory:
                setup = image_setup(path, pathlib.Path(directory)) if path.suffix == '.img' else path
                files = install_one(setup, keys[alias], profile, proton, env, timeout)
            records[job['sha256']] = {'prefix': token, 'files': files}
            temporary = work / 'installed.json.part'
            temporary.write_text(json.dumps({'schema': 1, 'installers': records}, indent=2), encoding='utf-8')
            os.replace(temporary, state_file)
            print('DLC ' + alias + ': installer completed and payload recorded. Verify loading and select content in the GIANTS web interface.', flush=True)
    finally:
        stop_process(display)

def load_amp_entries(base):
    config = base.parent / 'GenericModule.kvp'
    try:
        text = config.read_text(encoding='utf-8-sig')
        settings_lines = [line.partition('=')[2] for line in text.splitlines() if line.startswith('App.AppSettings=')]
        if len(settings_lines) != 1:
            raise ValueError
        settings = json.loads(settings_lines[0])
        if not isinstance(settings, dict):
            raise ValueError
        keys_text = settings.get('DLCProductKeysList', '')
        legacy_text = settings.get('DLCProductKeys', '')
        sources_text = settings.get('DLCInstallSources', '')
        if not isinstance(keys_text, str) or not isinstance(legacy_text, str) or not isinstance(sources_text, str):
            raise ValueError
        if not keys_text.strip():
            if '*' in legacy_text:
                raise DLCError('The legacy DLC password list contains mask characters. Enter the complete NAME=KEY entries in DLC Product Keys (List). No keys were inferred or logged.')
            keys_text = legacy_text
    except (OSError, UnicodeError, ValueError, TypeError):
        raise DLCError('DLC settings could not be read from the AMP instance configuration; no product keys were logged.') from None
    return parse_entries(keys_text, sources_text)

def main():
    if len(sys.argv) == 6 and sys.argv[1] == '--amp-settings':
        base, proton, prefix = (pathlib.Path(value).resolve() for value in sys.argv[2:5])
        keys, sources = load_amp_entries(base)
        timeout_text = sys.argv[5]
    elif len(sys.argv) == 7:
        base, proton, prefix = (pathlib.Path(value).resolve() for value in sys.argv[3:6])
        keys, sources = parse_entries(sys.argv[1], sys.argv[2])
        timeout_text = sys.argv[6]
    else:
        raise DLCError('Invalid DLC installation arguments.')
    if not keys:
        print('DLCs: disabled (no product keys configured).')
        return
    timeout = int(timeout_text)
    if not 60 <= timeout <= 7200:
        raise DLCError('DLC installer timeout must be between 60 and 7200 seconds.')
    work = base / 'work' / 'dlc'
    if not work.is_dir():
        raise DLCError('Run Update to prepare DLC downloads before starting.')
    import fcntl
    with (work / 'operation.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        install(base, proton, prefix, timeout, keys, sources)

if __name__ == '__main__':
    def interrupted(signum, frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupted)
    try:
        main()
    except KeyboardInterrupt:
        print('ERROR: DLC installation interrupted; no success marker was written for the active installer.', file=sys.stderr)
        sys.exit(130)
    except DLCError as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)
    except Exception:
        print('ERROR: DLC installation failed; check the prepared files, runtime dependencies and exclusive instance access. No success marker was written for the active installer.', file=sys.stderr)
        sys.exit(1)
